CREATE OR REPLACE FUNCTION private.capture_equipment_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.setup_versions; b public.basket_versions; g public.grinder_calibrations;
begin
 select * into strict v from public.setup_versions where id=new.setup_version_id and owner_id=new.owner_id and setup_id=new.setup_id;
 select * into strict b from public.basket_versions where id=new.basket_version_id and owner_id=new.owner_id and setup_id=new.setup_id;
 select * into strict g from public.grinder_calibrations where id=new.calibration_id and owner_id=new.owner_id and setup_id=new.setup_id;
 if v.grinder_model is distinct from g.grinder_model or v.burr_set is distinct from g.burr_set then
  raise exception using errcode='23514',message='Calibration does not match the recorded grinder and burrs.';
 end if;
 new.equipment_snapshot:=jsonb_build_object('machine_model',v.machine_model,'grinder_model',v.grinder_model,'burr_set',v.burr_set,
 'basket_model',b.model,'basket_dose_g',b.basket_dose_g,'finest_setting',g.finest_setting,'coarsest_setting',g.coarsest_setting);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.classify_personal_shot(shotid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.shots; fid uuid; previous uuid;
begin
 select * into strict s from public.shots where id=shotid;
 previous:=s.personal_family_id;
 -- Only an eligible green, visible shot can remain an explicit saved favorite.
 -- The stored shot ID is never redirected to another shot.
 if s.hidden_at is not null or not s.is_dialed_in then
  update public.recipe_preferences p set favorite_shot_id=null
   where p.owner_id=s.owner_id and p.favorite_shot_id=s.id;
 end if;
 if s.hidden_at is not null then
  if previous is not null then perform private.refresh_personal_family(previous); end if;
 else
  if s.is_dialed_in then
   select f.id into fid from public.personal_recipe_families f
    where f.owner_id=s.owner_id and f.library_entry_id=s.library_entry_id
     and f.style=s.style and f.evidence_state<>'retired'
     and abs(coalesce((f.statistics->'ratio'->>'center')::numeric,s.ratio)-s.ratio)<=.25
    order by abs(coalesce((f.statistics->'ratio'->>'center')::numeric,s.ratio)-s.ratio),f.created_at,f.id
    limit 1;
   if fid is null then
    insert into public.personal_recipe_families(owner_id,library_entry_id,style,statistics,estimator_version)
     values(s.owner_id,s.library_entry_id,s.style,
       jsonb_build_object('count',0,'ratio',jsonb_build_object('center',s.ratio)),
       'ratio_cluster_v1') returning id into fid;
   end if;
  end if;
  if s.personal_family_id is distinct from fid then
   update public.shots set personal_family_id=fid where id=shotid;
  end if;
  if previous is not null then perform private.refresh_personal_family(previous); end if;
  if fid is not null then
   perform private.refresh_personal_family(fid);
   insert into public.recipe_preferences(owner_id,setup_id,setup_version_id,library_entry_id,style,current_family_id)
    values(s.owner_id,s.setup_id,s.setup_version_id,s.library_entry_id,s.style,fid)
    on conflict(owner_id,setup_id,setup_version_id,library_entry_id,style)
    do update set current_family_id=coalesce(public.recipe_preferences.current_family_id,excluded.current_family_id);
   -- A manually selected example that is corrected into another eligible
   -- family remains the same deliberately selected example, not an auto choice.
   update public.recipe_preferences p set current_family_id=fid
    where p.owner_id=s.owner_id and p.favorite_shot_id=s.id
     and p.setup_version_id=s.setup_version_id
     and p.library_entry_id=s.library_entry_id and p.style=s.style
     and p.current_family_id is distinct from fid;
  end if;
 end if;
 -- Retire unsupported Current only after family refresh.
 update public.recipe_preferences p set current_family_id=null
  where p.owner_id=s.owner_id and p.library_entry_id=s.library_entry_id
   and p.current_family_id is not null and not exists(
    select 1 from public.shots x
     where x.owner_id=p.owner_id and x.setup_version_id=p.setup_version_id
      and x.library_entry_id=p.library_entry_id and x.style=p.style
      and x.personal_family_id=p.current_family_id and x.is_dialed_in
      and x.hidden_at is null);
end $function$

CREATE OR REPLACE FUNCTION private.dic_capture_recommendation_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare raw text; p jsonb; controls jsonb; tier text; label text;
 contributors integer; shots integer;
begin
 raw:=current_setting('dic.recommendation_context',true);
 if raw is null or length(raw)>800 then return new;end if;
 begin p:=raw::jsonb;exception when others then return new;end;
 if jsonb_typeof(p) is distinct from 'object' then return new;end if;
 controls:=p->'used_controls';
 if jsonb_typeof(controls) is distinct from 'array' or
    jsonb_array_length(controls) not between 1 and 2 then return new;end if;
 if exists(select 1 from jsonb_array_elements_text(controls) as x(control)
    where x.control not in ('grind','temperature')) then return new;end if;
 label:=left(coalesce(nullif(btrim(p->>'source_label'),''),'Starting recommendation'),90);
 tier:=case when p->>'community_tier' in ('exact','related_release','similar_coffee')
     then p->>'community_tier' else null end;
 contributors:=case when (p->>'contributor_count') ~ '^[0-9]{1,6}$'
     then least(100000,(p->>'contributor_count')::integer) else null end;
 shots:=case when (p->>'shot_count') ~ '^[0-9]{1,6}$'
     then least(100000,(p->>'shot_count')::integer) else null end;
 if contributors is null or shots is null or contributors<1 or shots<contributors then
  tier:=null;contributors:=null;shots:=null;
 end if;
 new.recommendation_context:=jsonb_build_object(
   'kind','member_selected_starting_reference',
   'source_label',label,'used_controls',controls,
   'community_tier',tier,'contributor_count',contributors,'shot_count',shots,
   'source_verified_independently',false);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.dic_claim_first_style_prompt_impl(p_library_entry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=private.require_member();claimed uuid;
begin
 if p_library_entry_id is null or not exists(
  select 1 from public.library_entries l where l.owner_id=u and l.id=p_library_entry_id and l.hidden_at is null
 ) then raise exception using errcode='42501',message='Coffee is not accessible.'; end if;
 if exists(select 1 from public.shots s where s.owner_id=u and s.library_entry_id=p_library_entry_id) then
  return jsonb_build_object('ok',true,'show',false);
 end if;
 insert into private.dic_first_style_prompt_seen(owner_id,library_entry_id)
 values(u,p_library_entry_id) on conflict(owner_id,library_entry_id) do nothing
 returning library_entry_id into claimed;
 return jsonb_build_object('ok',true,'show',claimed is not null);
end $function$
